public static void main(String[] args){
  Scanner sc = new Scanner(System.in);
  String S = sc.next();
  int number = Integer.parseInt(S.substring(3));
  if(number == 316 || number < 1 || number > 349){
    System.out.print("No");
  }else{
    System.out.print("Yes");
  }
  sc.close();
}

